// Shared identity and navigation for the town, portfolio and storefronts.
window.shopUi = (() => {
  const names={wine:['Wine store','Weinhandlung'],toys:['Toy store','Spielwarenladen'],electronics:['Electronics store','Elektronikladen'],cars:['Car dealership','Autohaus'],jeweler:['Jeweler','Juwelier'],hardware:['Hardware store','Baumarkt']};
  const stockHint=id=>id==='jeweler'?t('Jewelry & watches','Schmuck & Uhren'):id==='hardware'?t('Tools & Other','Werkzeuge & Sonstiges'):'';
  const sizes={popup:['Street pop-up','Straßenstand'],tiny:['Small shop','Kleiner Laden'],medium:['Medium shop','Mittlerer Laden'],large:['Large shop','Großer Laden']};
  const typeName=id=>names[id]?t(...names[id]):id,sizeName=id=>sizes[id]?t(...sizes[id]):id,esc=accountEscape;
  function art(type){return `<span class="shop-illustration shop-color-${esc(type)}">${window.townArtwork.storefront()}<span class="shop-product">${window.townArtwork.icon(type)}</span></span>`;}
  function address(shop){const p=shop.location||shop;return p.districtName?`${p.districtNumber||''}. ${p.districtName} · ${p.streetName||''}`:'';}
  function returnTo(){const value=new URLSearchParams(location.search).get('returnTo');try{const url=new URL(value||'/stores',location.origin);return url.origin===location.origin&&['/town','/businesses','/stores'].includes(url.pathname)?url.pathname+url.search:'/stores';}catch{return '/stores';}}
  function href(shop,tab='overview'){return `/stores?${new URLSearchParams({shop:shop.id,...(tab==='overview'?{}:{tab}),returnTo:location.pathname==='/town'?location.pathname+location.search:location.pathname==='/businesses'?'/businesses':location.pathname==='/stores'&&!new URLSearchParams(location.search).has('shop')?location.pathname+location.search:returnTo()})}`;}
  const colors={forest:['Forest','Waldgrün'],ocean:['Ocean','Ozeanblau'],plum:['Plum','Pflaume'],berry:['Berry','Beere'],amber:['Amber','Bernstein'],slate:['Slate','Schiefer']};
  const defaultColors={wine:'berry',toys:'plum',electronics:'ocean',cars:'slate',jeweler:'amber',hardware:'forest'};
  const color=shop=>Object.hasOwn(colors,shop.color)?shop.color:defaultColors[shop.type]||'forest';
  function imageUrl(value){const match=typeof value==='string'&&value.trim().match(/^https:\/\/(?:i\.|www\.)?imgur\.com\/([a-zA-Z0-9]{5,12})(\.(?:png|jpe?g|gif|webp))?$/);return match?`https://i.imgur.com/${match[1]}${match[2]||'.png'}`:'';}
  function banner(shop){const url=imageUrl(shop.bannerUrl);return `<div class="store-brand-banner brand-${color(shop)}">${url?`<img src="${esc(url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`: `<span class="store-banner-orbit" aria-hidden="true"></span>${art(shop.type)}`}</div>`;}
  function icon(shop){const url=imageUrl(shop.iconUrl);return `<span class="store-brand-icon brand-${color(shop)}">${url?`<img src="${esc(url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:window.townArtwork.icon(shop.type)}</span>`;}
  // Failed custom media reveals its existing fallback without an inline handler.
  document.addEventListener('error',event=>{const img=event.target;if(img.matches?.('.store-brand-banner img,.store-brand-icon img')){const host=img.parentElement;host.innerHTML=host.classList.contains('store-brand-icon')?window.townArtwork.icon('bag'):'<span class="store-banner-orbit" aria-hidden="true"></span>';host.classList.add('has-image-error');}},true);
  function header(shop){return `<header class="shop-header branded-shop-header brand-${color(shop)}">${banner(shop)}<div class="shop-identity">${icon(shop)}<div><span class="shop-kicker">${esc(typeName(shop.type))} · ${esc(sizeName(shop.size))}${shop.abandoned?` · ${t('Abandoned','Verlassen')}`:''}</span><h1 tabindex="-1">${esc(shop.name||typeName(shop.type))}</h1>${shop.motto?`<p>${esc(shop.motto)}</p>`:''}${address(shop)?`<a href="/town?plot=${encodeURIComponent(shop.location?.plotId||shop.plotId||'')}" data-page>${esc(address(shop))} ↗</a>`:''}${window.storeReputationUi?.meter(shop)||''}${shop.abandoned?`<a href="/town?plot=${encodeURIComponent(shop.location?.plotId||'')}" data-page>${t('Abandoned · view purchase options','Verlassen · Kaufoptionen ansehen')} →</a>`:''}</div></div></header>`;}
  function card(shop,action='visit'){return `<article class="market-store-card brand-${color(shop)}">${banner(shop)}<div class="market-store-body"><div class="market-store-identity">${icon(shop)}<span class="market-store-category">${esc(typeName(shop.type))}</span>${shop.ownerId===account?.id?`<span class="market-own-badge">${t('Yours','Deiner')}</span>`:''}</div><h2><a href="${esc(href(shop))}" data-page>${esc(shop.name||typeName(shop.type))}</a></h2><span class="market-store-owner">@${esc(shop.owner||account?.username||'')}</span><p class="market-store-address">${window.townArtwork.icon('pin')}${esc(address(shop))}</p>${shop.motto?`<p class="market-store-motto">${esc(shop.motto)}</p>`:''}<div class="market-store-rating">${shop.rating==null?`<span class="market-unrated">${t('No reviews yet','Noch keine Bewertungen')}</span>`:`<span aria-hidden="true">★</span><strong>${number(shop.rating,1)}</strong><span>(${number(shop.reviewCount)})</span>`}</div><div class="market-store-footer"><span class="market-stock ${shop.stockCount?'is-stocked':''}"><i aria-hidden="true"></i>${shop.abandoned?t('Abandoned','Verlassen'):shop.stockCount?`${number(shop.stockCount)} ${t('in stock','auf Lager')}`:t('Restocking','Wird aufgefüllt')}</span><a class="market-visit" href="${esc(href(shop))}" data-page aria-label="${esc((action==='manage'?t('Manage','Verwalten'):t('Shop','Einkaufen'))+' · '+(shop.name||typeName(shop.type)))}">${action==='manage'?t('Manage','Verwalten'):t('Shop','Einkaufen')} <span aria-hidden="true">↗</span></a></div></div></article>`;}
  function handoff(){const id=new URLSearchParams(location.search).get('returnShop');return id?`<a class="shop-handoff" href="/stores?${new URLSearchParams({shop:id,tab:'stock',returnTo:returnTo()})}" data-page>← ${t('Return to store stock','Zurück zum Ladenbestand')}</a>`:'';}
  return {colors,color,banner,icon,stockHint,handoff,typeName,sizeName,art,address,header,card,href,returnTo};
})();
